for tid,titulo,txt,qs in textos:
    for q,c,o,e in qs:add('lectura',tid+' - '+titulo,q,c,o,e,'Texto original de práctica '+tid+'; NO examen ni texto oficial',txt)

assert len(preguntas)==180
assert len({p['id'] for p in preguntas})==180
for p in preguntas:
    esperado=3 if p['etapa']=='lectura' else 4
    assert len(p['opciones'])==esperado and len(set(p['opciones']))==esperado
    assert 0<=p['correcta']<esperado
Path('preguntas.json').write_text(json.dumps(preguntas,ensure_ascii=False,indent=2),encoding='utf-8')
Path('textos.json').write_text(json.dumps([dict(id=i,titulo=t,texto=x) for i,t,x,_ in textos],ensure_ascii=False,indent=2),encoding='utf-8')
print('180 preguntas: 100 específicos,40 institucionales,40 lectura; estructura y claves verificadas.')
